import { Component, inject } from '@angular/core';
import { RouterModule } from '@angular/router';
import { combineLatest } from 'rxjs';
import { AuthFacade } from '../../../app/core/auth/store/auth.facades';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-navbar',
  imports: [RouterModule , CommonModule],
  templateUrl: './navbar.component.html',
  styleUrl: './navbar.component.css'
})
export class NavbarComponent {
  private readonly authFacade : AuthFacade = inject(AuthFacade)

  readonly _vm = combineLatest({
    isAuthenticated : this.authFacade._isAuthenticated,
  })

  logout() : void {
    this.authFacade.logout()
  }
}

@if(_vm | async; as vm) {
    <nav>
        <ul class="flex">
            <li class="mx-2">
                <a [routerLink]="['/']" class=" text-base hover:text-primary duration-300 ease-linear" routerLinkActive="text-primary" >Home</a>
            </li>
            <li class="mx-2">
                <a [routerLink]="['/resturants']" class="text-base hover:text-primary duration-300 ease-linear" routerLinkActive="text-primary" >Resturants</a>
            </li>
            @if (!vm.isAuthenticated) {
                <li class="mx-2">
                    <a [routerLink]="['/auth/login']" class="text-base hover:text-primary duration-300 ease-linear" routerLinkActive="text-primary" >Login</a>
                </li>
            }@else {
                <li class="mx-2">
                    <button (click)="logout()" class="text-base hover:text-primary duration-300 ease-linear" routerLinkActive="text-primary" >Logout</button>
                </li>
            }
        </ul>
    </nav>
}
